import * as React from "react"
import { navigate } from "gatsby"
import Header from "../components/Header"
import Seo from "../components/Seo"
import PageSpinner from "../components/PageSpinner"
import { configured } from "../lib/supabase"
import { useAuth } from "../context/auth"
import { AFFILIATE_MESSAGES, affiliateFor } from "../lib/affiliate"
import * as s from "../components/admin/Admin.module.css"

/**
 * /affiliate — MTC-FCS-041, folded into the account screen by FCS-110.
 * ============================================================================
 * The report used to be this page: its own screen, with the website builder's
 * button in the header and none of the account menu around it. An affiliate's
 * dashboard is now /account/ (Dashboard, Affiliate, Billing, Settings), so an
 * approved affiliate who opens this address — from an old bookmark, an email, a
 * link in an advert — is sent there.
 *
 * Everybody else is still told why this is not theirs, each in their own words:
 * see AFFILIATE_MESSAGES for why "we could not check" must never read as "you
 * are not one".
 */

const Shell = ({ title, children }) => (
  <>
    <Header />
    <main className={s.page}>
      <div className="container">
        {title ? <h1 className={s.title}>{title}</h1> : null}
        {children}
      </div>
    </main>
  </>
)

const AffiliatePage = () => {
  const { user, ready } = useAuth()
  const [role, setRole] = React.useState({ status: "checking", affiliate: null })

  React.useEffect(() => {
    if (!ready) return
    if (!user) {
      setRole({ status: "anonymous", affiliate: null })
      return
    }
    affiliateFor(user).then(setRole)
  }, [ready, user])

  React.useEffect(() => {
    if (role.status === "active") navigate("/account/#affiliate", { replace: true })
  }, [role.status])

  if (!configured()) {
    return (
      <Shell title="Your adverts">
        <p className={s.lead}>Accounts are not set up on this environment.</p>
      </Shell>
    )
  }

  // Nothing until we know who this is: the zeroes of an empty report are nobody's numbers.
  if (!ready || role.status === "checking" || role.status === "active") {
    return (
      <Shell title="">
        <PageSpinner label="Taking you to your account…" />
      </Shell>
    )
  }

  if (!user) {
    return (
      <Shell title="Your adverts">
        <p className={s.lead}>
          Log in to see which of your images brought people in, and which groups they came from. It is the same
          account you use everywhere else here.
        </p>
        <button type="button" className={s.button} onClick={() => navigate("/log-in?next=/account/")}>
          Log in
        </button>
      </Shell>
    )
  }

  const message = AFFILIATE_MESSAGES[role.status] || AFFILIATE_MESSAGES.unknown
  return (
    <Shell title={message.title}>
      <p className={s.lead}>{message.body}</p>
    </Shell>
  )
}

export const Head = () => (
  <Seo title="Your adverts" description="Which of your adverts and groups brought people in." noindex />
)

export default AffiliatePage
